#include <vector>
using namespace std;

vector<int> selection_sort(vector<int> v) {
    int n = (int)v.size();
    for (int i = 0; i < n - 1; i++) {
        int m = i;
        for (int j = i + 1; j < n; j++)
            if (v[j] < v[m]) m = j;
        if (m != i) {
            int t = v[i];
            v[i] = v[m];
            v[m] = t;
        }
    }
    return v;
