// Comparisons for Early-Stop Bubble (full scans; stop after a no-swap pass)
#include <iostream>
#include <vector>
using namespace std;

int bubble_comparisons(vector<int> v) {
    int n = (int)v.size(), comps = 0;
    bool swapped = true;
    while (swapped) {
        swapped = false;
        for (int j = 0; j < n - 1; j++) {
            comps++;
            if (v[j] > v[j + 1]) {
                int t = v[j];
                v[j] = v[j + 1];
                v[j + 1] = t;
                swapped = true;
            }
        }
    }
    return comps;
}

int main() {
    int n;
    if (!(cin >> n)) return 0;
    vector<int> v(n);
    for (int i = 0; i < n; i++) cin >> v[i];
    cout << bubble_comparisons(v) << "\n";
    return 0;
}

// Passes Until the Deck Is Sorted (includes the final no-swap pass)
#include <iostream>
#include <vector>
using namespace std;

int bubble_passes(vector<int> v) {
    int n = (int)v.size(), passes = 0;
    bool swapped = true;
    while (swapped) {
        swapped = false;
        passes++;
        for (int j = 0; j < n - 1; j++)
            if (v[j] > v[j + 1]) {
                int t = v[j];
                v[j] = v[j + 1];
                v[j + 1] = t;
                swapped = true;
            }
    }
    return passes;
}

int main() {
    int n;
    if (!(cin >> n)) return 0;
    vector<int> v(n);
    for (int i = 0; i < n; i++) cin >> v[i];
    cout << bubble_passes(v) << "\n";
    return 0;
}

