// Wordlist by Length Then Alphabet (insertion with two-part comparison)
#include <iostream>
#include <string>
#include <vector>
using namespace std;

vector<string> order_words(vector<string> words) {
    int n = (int)words.size();
    for (int i = 1; i < n; i++) {
        string key = words[i];
        int j = i - 1;
        while (j >= 0 && (words[j].size() > key.size() ||
                          (words[j].size() == key.size() && words[j] > key))) {
            words[j + 1] = words[j];
            j--;
        }
        words[j + 1] = key;
    }
    return words;
}

int main() {
    int n;
    if (!(cin >> n)) return 0;
    vector<string> words(n);
    for (int i = 0; i < n; i++) cin >> words[i];
    vector<string> res = order_words(words);
    for (int i = 0; i < n; i++)
        cout << res[i] << (i + 1 < n ? ' ' : '\n');
    return 0;
}

